import { test } from "node:test";
import assert from "node:assert/strict";
import { calcTotal } from "../src/pricing.ts";

test("calcTotal: no discount under 10 units", () => {
  // 9 units, $27 total
  assert.equal(calcTotal([{ sku: "a", price: 3, qty: 5 }, { sku: "b", price: 3, qty: 4 }]), 27);
});

test("calcTotal: 10% off at exactly 10 units", () => {
  // 10 units, $30 subtotal -> $27
  assert.equal(calcTotal([{ sku: "a", price: 3, qty: 6 }, { sku: "b", price: 3, qty: 4 }]), 27);
});

test("calcTotal: 10% off above 10 units", () => {
  // 12 units, $40 subtotal -> $36
  assert.equal(calcTotal([{ sku: "a", price: 2, qty: 8 }, { sku: "b", price: 6, qty: 4 }]), 36);
});

